using IptvManagement.Domain.Enums; using IptvManagement.Infrastructure.Data; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Hosting; using Microsoft.Extensions.Logging;
namespace IptvManagement.Infrastructure.Services;
public class ExpiredSubscriptionWorker(IServiceScopeFactory scopes,ILogger<ExpiredSubscriptionWorker> logger):BackgroundService{ protected override async Task ExecuteAsync(CancellationToken stoppingToken){ using var timer=new PeriodicTimer(TimeSpan.FromHours(1)); while(await timer.WaitForNextTickAsync(stoppingToken)){ using var scope=scopes.CreateScope(); var db=scope.ServiceProvider.GetRequiredService<AppDbContext>(); var now=DateTime.UtcNow; var affected=await db.Subscriptions.Where(s=>s.Status==SubscriptionStatus.Active&&s.ExpirationDateUtc<=now).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.Status,SubscriptionStatus.Expired),stoppingToken); if(affected>0) logger.LogInformation("{Count} Abonnements als abgelaufen markiert.",affected); } }}
public class ActivationCodeCleanupWorker(IServiceScopeFactory scopes):BackgroundService{ protected override async Task ExecuteAsync(CancellationToken stoppingToken){ using var timer=new PeriodicTimer(TimeSpan.FromHours(6)); while(await timer.WaitForNextTickAsync(stoppingToken)){ using var scope=scopes.CreateScope(); var db=scope.ServiceProvider.GetRequiredService<AppDbContext>(); await db.DeviceActivationCodes.Where(c=>c.ExpiresAtUtc<DateTime.UtcNow||c.UsedAtUtc!=null).ExecuteDeleteAsync(stoppingToken); } }}
